pub fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // list is non-empty and 1 <= k < list.len()
    let n = list.len();
    assert!(k >= 1 && k < n, "k must be between 1 and n-1");

    // Allocate a new vector of size n-1
    let mut new_list = Vec::with_capacity(n - 1);

    // Extend with elements before the k-th (1-based) element
    new_list.extend_from_slice(&list[..(k - 1)]);
    // Extend with elements after the k-th (1-based) element
    new_list.extend_from_slice(&list[k..]);

    new_list
}

